export const getGetCurrentClanPeriodUrl = (params: GetCurrentClanPeriodParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/bridge/clans/current-period?${stringifiedParams}` : `/api/bridge/clans/current-period`
}

